/**
 * glTF asset library. Models live in `src/assets/models/**.glb` (generated by `tools/assets/*.py`,
 * see docs/ASSET_PIPELINE.md). Vite's glob import discovers whichever files exist and gives each a
 * base-path-safe URL, so a missing model simply is not registered and callers can fall back.
 *
 * Conventions: Y-up, metres, front = +Z, origin on the ground at the model's centre.
 */
import type { AnimationClip, BufferGeometry, Material, Mesh, Object3D, Texture } from 'three';
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';
import { clone } from 'three/addons/utils/SkeletonUtils.js';

const urls = import.meta.glob('../../assets/models/**/*.glb', {
  query: '?url',
  import: 'default',
  eager: true,
}) as Record<string, string>;

/** Asset id = file name without extension, e.g. `char_streetBaller`. */
const URL_BY_ID = new Map<string, string>(
  Object.entries(urls).map(([path, url]) => [
    path
      .split('/')
      .pop()!
      .replace(/\.glb$/, ''),
    url,
  ]),
);

/**
 * Anisotropic filtering for every texture of a loaded model. glTF textures default to none, which
 * smears atlases on surfaces seen at a grazing angle (wall faces, crate sides, vehicle flanks) under
 * the low 3/4 camera. three.js clamps the value to what the GPU supports.
 */
export const MODEL_ANISOTROPY = 8;

function sharpenTextures(root: Object3D): void {
  root.traverse((o) => {
    const m = o as Mesh;
    if (!m.isMesh) return;
    for (const mat of Array.isArray(m.material) ? m.material : [m.material]) {
      for (const v of Object.values(mat as unknown as Record<string, unknown>)) {
        const t = v as Texture | null;
        if (t && (t as { isTexture?: boolean }).isTexture) t.anisotropy = MODEL_ANISOTROPY;
      }
    }
  });
}

export interface LoadedAsset {
  scene: Object3D;
  clips: AnimationClip[];
}

export class AssetLibrary {
  private readonly assets = new Map<string, LoadedAsset>();
  private readonly loader = new GLTFLoader();
  private failed: string[] = [];

  /** Ids of every model file bundled with the build. */
  static availableIds(): string[] {
    return [...URL_BY_ID.keys()];
  }

  /** Ids of the models that finished loading (sorted, so derived choices are stable). */
  loadedIds(prefix = ''): string[] {
    return [...this.assets.keys()].filter((i) => i.startsWith(prefix)).sort();
  }

  has(id: string): boolean {
    return this.assets.has(id);
  }

  /** Loads the listed models (or all bundled ones) in parallel. Failures are reported, never thrown. */
  async preload(
    ids: string[] = AssetLibrary.availableIds(),
    onProgress?: (done: number, total: number) => void,
  ): Promise<string[]> {
    const failed: string[] = [];
    let done = 0;
    await Promise.all(
      ids.map(async (id) => {
        const url = URL_BY_ID.get(id);
        try {
          if (!url) throw new Error('not bundled');
          const gltf = await this.loader.loadAsync(url);
          sharpenTextures(gltf.scene);
          this.assets.set(id, { scene: gltf.scene, clips: gltf.animations });
        } catch (error) {
          console.warn(`[assets] ${id} failed to load`, error);
          failed.push(id);
        } finally {
          onProgress?.(++done, ids.length);
        }
      }),
    );
    this.failed = failed;
    return failed;
  }

  failedIds(): string[] {
    return [...this.failed];
  }

  /** A fresh, independently animatable copy (skeletons are re-bound). Returns null if the asset is unavailable. */
  instance(id: string): Object3D | null {
    const a = this.assets.get(id);
    if (!a) return null;
    const obj = clone(a.scene);
    obj.traverse((o) => {
      const m = o as Mesh;
      if (m.isMesh) {
        m.castShadow = true;
        m.receiveShadow = true;
        m.frustumCulled = false; // skinned bounds are unreliable under animation
      }
    });
    return obj;
  }

  clips(id: string): AnimationClip[] {
    return this.assets.get(id)?.clips ?? [];
  }

  /** First mesh of an asset (geometry + material), for building InstancedMeshes from static props. */
  firstMesh(id: string): Mesh | null {
    let found: Mesh | null = null;
    this.assets.get(id)?.scene.traverse((o) => {
      const m = o as Mesh;
      if (!found && m.isMesh) found = m;
    });
    return found;
  }

  /**
   * Geometry + material of every mesh in an asset with node transforms baked into the vertices, ready for
   * `InstancedMesh`. Optionally only meshes whose node name matches `filter`.
   */
  parts(
    id: string,
    filter?: (name: string) => boolean,
  ): { name: string; geometry: BufferGeometry; material: Material }[] {
    const scene = this.assets.get(id)?.scene;
    if (!scene) return [];
    scene.updateMatrixWorld(true);
    const out: { name: string; geometry: BufferGeometry; material: Material }[] = [];
    scene.traverse((o) => {
      const m = o as Mesh;
      if (!m.isMesh || (filter && !filter(m.name))) return;
      const g = m.geometry.clone();
      g.applyMatrix4(m.matrixWorld);
      out.push({
        name: m.name,
        geometry: g,
        material: Array.isArray(m.material) ? m.material[0]! : m.material,
      });
    });
    return out;
  }

  /** All meshes of an asset with their world matrices applied to a clone of the geometry (see props code). */
  meshes(id: string): Mesh[] {
    const out: Mesh[] = [];
    const scene = this.assets.get(id)?.scene;
    scene?.updateMatrixWorld(true);
    scene?.traverse((o) => {
      const m = o as Mesh;
      if (m.isMesh) out.push(m);
    });
    return out;
  }

  dispose(): void {
    for (const a of this.assets.values()) {
      a.scene.traverse((o) => {
        const m = o as Mesh;
        if (!m.isMesh) return;
        m.geometry.dispose();
        for (const mat of Array.isArray(m.material) ? m.material : [m.material]) (mat as Material).dispose();
      });
    }
    this.assets.clear();
  }
}

/** Process-wide library: models are loaded once and shared by every match. */
export const assets = new AssetLibrary();
